import{_ as t,C as s,o as a,c as o,j as i,a as p,E as r,a3 as d}from"./chunks/framework.DEy3KOfk.js";const v=JSON.parse('{"title":"Sign Pumpkin plugins","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/actions/sign-pumpkin-plugin/docs/index.md"},"headers":[],"relativePath":"actions/sign-pumpkin-plugin/docs/index.md","filePath":"actions/sign-pumpkin-plugin/docs/index.md","lastUpdated":1791513651000}'),l={name:"actions/sign-pumpkin-plugin/docs/index.md"},c={id:"sign-pumpkin-plugins",tabindex:"-1",class:"component-page-title"},u={class:"component-page-title__version",href:"https://github.com/filiphsps/pumpkin-plugins/releases/tag/sign-pumpkin-plugin-v0.0.3","aria-label":"Release v0.0.3"};function g(m,e,h,f,_,k){const n=s("Badge");return a(),o("div",null,[i("h1",c,[e[0]||(e[0]=i("span",{class:"component-page-title__text"},[p("Sign Pumpkin plugins "),i("a",{class:"header-anchor",href:"#sign-pumpkin-plugins","aria-label":'Permalink to "Sign Pumpkin plugins"'},"​")],-1)),i("a",u,[r(n,{type:"info",text:"v0.0.3"})])]),e[1]||(e[1]=d('<p>The signing action adds Pumpkin&#39;s Ed25519 signature and release metadata to one or more existing plugin <code>.wasm</code> files. It signs in place and does not build them. Run it on the exact artifact from the build job, before publishing or distributing that artifact.</p><p>For a workflow example and the complete input list, see the <a href="./../README">action README</a>.</p><p>For one file, provide the plugin name, version without a leading <code>v</code>, and wasm path. For a release with several plugins, use <code>plugins-manifest</code>, a JSON array of those three values; the developer name and key apply to every item. The action replaces existing signing sections, verifies the result before writing, and refreshes an adjacent <code>.sha256</code> file when one exists.</p><p>Store the 32-byte Ed25519 seed as 64 hexadecimal characters in a protected GitHub secret. Set <code>warn: true</code> only when a missing key should intentionally leave files unsigned, such as a fork workflow. Malformed keys, missing files, and failed verification remain errors. The action runs on GitHub Actions&#39; Node 24 runtime and needs no setup step.</p>',4))])}const b=t(l,[["render",g]]);export{v as __pageData,b as default};
